<?php

declare(strict_types=1);

namespace App\Generated;

use AIC\Component\Application\RenderPass;
use AIC\Component\Domain\ThemeLayout;
use AIC\Component\Exception\UnknownComponent;

/**
 * Generated by composer run build from the configured theme (#154) (#92): the document adapter.
 * Do not edit; change the manifest and run composer run build.
 */
final readonly class ThemeHtmlTemplate
{
    /**
     * @param ThemeLayout $themeLayout The document.
     * @param RenderPass  $renderPass  The pass that writes its children.
     *
     * @throws UnknownComponent When a child has no registered template.
     *
     * @return string The layout's document markup; html.phtml's when it ships no html of its own.
     */
    public function render(ThemeLayout $themeLayout, RenderPass $renderPass): string
    {
        return match ($themeLayout->page->layout) {
            'plain' => $this->renderHtmlPlain($themeLayout, $renderPass),
            default => $this->renderHtml($themeLayout, $renderPass),
        };
    }

    /**
     * @param ThemeLayout $themeLayout The component; its template reads it.
     * @param RenderPass  $renderPass  The pass its template writes through.
     *
     * @throws UnknownComponent When a child has no template.
     *
     * @return string Its markup, from templates/themes/app/layouts/html.phtml.
     */
    private function renderHtml(ThemeLayout $themeLayout, RenderPass $renderPass): string
    {
        $renderPass->open($themeLayout);
        require __DIR__ . '/templates/themes/app/layouts/html.phtml';

        return $renderPass->close();
    }

    /**
     * @param ThemeLayout $themeLayout The component; its template reads it.
     * @param RenderPass  $renderPass  The pass its template writes through.
     *
     * @throws UnknownComponent When a child has no template.
     *
     * @return string Its markup, from templates/themes/app/layouts/html--plain.phtml.
     */
    private function renderHtmlPlain(ThemeLayout $themeLayout, RenderPass $renderPass): string
    {
        $renderPass->open($themeLayout);
        require __DIR__ . '/templates/themes/app/layouts/html--plain.phtml';

        return $renderPass->close();
    }
}
